//! Compiled template representation.
//!
//! The statements mirror, one to one, the Python code generated by
//! `IrQweb._generate_code`, so the runtime reproduces its behaviour exactly
//! (including the `attrs` local and the `t-options` register).
//!
//! Values, keys and host-compiled expressions are stored as the host's own
//! types ([`Host::Value`], [`Host::Key`], [`Host::Opaque`]), created once at
//! compile time.

use std::sync::{Arc, OnceLock};

use crate::expr::{BinOp, CmpOp, UnOp};
use crate::host::{Host, TemplateRef};
use crate::xml::{Document, NodeId, NsMap};

/// Lowered expression, ready for evaluation by a host.
///
/// Literals are already host values, and tuples of constants are folded.
pub enum Ex<H: Host> {
    /// Constant value (literals, builtins, folded tuples).
    Const(H::Value),
    /// Template value lookup. `strict`: `values['x']`, else `values.get('x')`.
    Var {
        /// Interned name.
        key: H::Key,
        /// Name, for the error raised by a strict lookup.
        name: Arc<str>,
        /// Raise `KeyError` when the name is missing (instead of `None`).
        strict: bool,
    },
    /// Builtin name unknown to the host, or integer literal the host cannot
    /// represent: raises `NameError` when evaluated.
    Unknown(Arc<str>),
    /// `obj.name`
    Attr(Box<Ex<H>>, H::Key),
    /// `obj[key]`
    Item(Box<Ex<H>>, Box<Ex<H>>),
    /// `slice(lower, upper, step)` (subscript `lower:upper:step`).
    Slice(Option<Box<Ex<H>>>, Option<Box<Ex<H>>>, Option<Box<Ex<H>>>),
    /// `func(*args, **kwargs)`
    Call {
        /// Called expression.
        func: Box<Ex<H>>,
        /// Positional arguments.
        args: Vec<Ex<H>>,
        /// Keyword arguments, in source order.
        kwargs: Vec<(H::Key, Ex<H>)>,
    },
    /// Unary arithmetic operator.
    Unary(UnOp, Box<Ex<H>>),
    /// `not x`
    Not(Box<Ex<H>>),
    /// Binary arithmetic operator.
    Bin(BinOp, Box<Ex<H>>, Box<Ex<H>>),
    /// Comparison chain `first op1 e1 op2 e2 ...` (never empty).
    Cmp(Box<Ex<H>>, Vec<(CmpOp, Ex<H>)>),
    /// `a and b and ...` (short-circuit, returns the deciding operand).
    And(Vec<Ex<H>>),
    /// `a or b or ...` (short-circuit, returns the deciding operand).
    Or(Vec<Ex<H>>),
    /// `then if cond else orelse`, stored as `(cond, then, orelse)`.
    IfElse(Box<Ex<H>>, Box<Ex<H>>, Box<Ex<H>>),
    /// Tuple display.
    Tuple(Vec<Ex<H>>),
    /// List display.
    List(Vec<Ex<H>>),
    /// Set display.
    Set(Vec<Ex<H>>),
    /// Dict display.
    Dict(Vec<(Ex<H>, Ex<H>)>),
    /// Expression compiled by the host ([`Host::compile_opaque`]).
    Opaque(Box<H::Opaque>),
}

/// Format string (`t-attf-*`, `t-valuef`, ...).
pub enum Format<H: Host> {
    /// No interpolation: the literal string value.
    Const(H::Value),
    /// Literal text and interpolated expressions, concatenated.
    Parts(Vec<FormatPart<H>>),
}

/// A piece of a [`Format`].
pub enum FormatPart<H: Host> {
    /// Literal text.
    Lit(Box<str>),
    /// Interpolated expression (`None`/`False` give `''`).
    Expr(Ex<H>),
}

/// Value of an attribute set by [`Stmt::AttrSet`].
pub enum AttrSrc<H: Host> {
    /// Static attribute value (a str).
    Static(Arc<str>),
    /// `t-att-<name>` expression.
    Expr(Ex<H>),
    /// `t-attf-<name>` format string.
    Format(Format<H>),
}

/// Location of the element a statement comes from (error reporting).
///
/// Usually just a node id: the text is built by [`Program::location`] only
/// when an error is reported, from the template source parsed again.
#[derive(Clone)]
pub struct Loc(LocKind);

#[derive(Clone)]
enum LocKind {
    /// Element of the template source, unchanged when it was recorded.
    Node(NodeId),
    /// Text built when recorded (element changed since parsing, or no source).
    Text(Arc<LocText>),
}

/// Location text: XPath and start tag of an element.
pub struct LocText {
    /// XPath of the element.
    pub path: Arc<str>,
    /// Start tag of the element, with its attributes before compilation.
    pub element: Arc<str>,
}

impl Loc {
    /// Location of node `id` of the template source, as parsed.
    pub(crate) fn node(id: NodeId) -> Self {
        Loc(LocKind::Node(id))
    }

    /// Location of element `id` in its current state.
    pub(crate) fn current(doc: &Document, id: NodeId) -> Self {
        Loc(LocKind::Text(Arc::new(LocText {
            path: Arc::from(doc.path(id)),
            element: Arc::from(doc.start_tag_repr(id)),
        })))
    }
}

/// The template source, parsed again (once) to build location texts.
pub(crate) struct LocSource {
    source: Option<Arc<str>>,
    doc: OnceLock<Option<Document>>,
}

impl LocSource {
    pub(crate) fn new(source: Option<Arc<str>>) -> Self {
        LocSource {
            source,
            doc: OnceLock::new(),
        }
    }

    pub(crate) fn has_source(&self) -> bool {
        self.source.is_some()
    }

    /// `(path, element)` of a location.
    pub(crate) fn resolve(&self, loc: &Loc) -> (Arc<str>, Arc<str>) {
        match &loc.0 {
            LocKind::Text(t) => (t.path.clone(), t.element.clone()),
            LocKind::Node(id) => {
                let doc = self
                    .doc
                    .get_or_init(|| self.source.as_deref().and_then(|s| Document::parse(s).ok()));
                match doc {
                    Some(d) if *id < d.nodes.len() => {
                        (Arc::from(d.path(*id)), Arc::from(d.start_tag_repr(*id)))
                    }
                    // not reachable: node locations are only recorded with a source
                    _ => (Arc::from(""), Arc::from("")),
                }
            }
        }
    }
}

/// What a [`Out`] statement outputs.
pub enum OutContent<H: Host> {
    /// `t-out` expression.
    Expr(Ex<H>),
    /// `values.get(0, '')` (the `t-call` body used with options).
    Slot,
    /// `t-field="record.field"`.
    Field {
        /// The record expression (`record`).
        record: Ex<H>,
        /// The field name.
        field: Box<str>,
    },
}

/// What a [`Out`] statement does when its content is `None` or `False`.
pub enum Otherwise<H: Host> {
    /// `else:` tag with default content.
    Default(Vec<Stmt<H>>),
    /// Widget/field: `elif force_display:` (if the tag has output) then `else: attrs = None`.
    ForceDisplay {
        /// Whether the element renders a start or end tag.
        has_tag: bool,
    },
    /// Output nothing.
    Nothing,
}

/// `t-out` / `t-field`, with the element around it.
pub struct Out<H: Host> {
    /// The value to output.
    pub content: OutContent<H>,
    /// Widget/field conversion (`t-options` consumed or `t-field`).
    pub convert: Option<Convert>,
    /// Start tag (run when there is content).
    pub tag_open: Vec<Stmt<H>>,
    /// End tag (run when there is content).
    pub tag_close: Vec<Stmt<H>>,
    /// What to do without content.
    pub otherwise: Otherwise<H>,
    /// Location of the element.
    pub loc: Loc,
}

/// Conversion of an [`Out`] value through [`Host::get_field`] or [`Host::get_widget`].
pub struct Convert {
    /// `t-field` (else a `t-out` widget).
    pub field: bool,
    /// Original expression (`expression` option).
    pub expression: Box<str>,
    /// Element tag (`tagName` option).
    pub tag: Box<str>,
    /// Merge into existing `attrs` (`qweb_attrs_created`) instead of replacing.
    pub merge: bool,
}

/// An argument of a `t-call`, evaluated in the caller's scope.
pub enum CallArg<H: Host> {
    /// `name="expr"`.
    Expr(H::Key, Ex<H>),
    /// `name.f="format"` (or `.translate` outside translation edition).
    Format(H::Key, Format<H>),
    /// `name.translate="format"` in translation edition: a `Markup` value.
    MarkupFormat(H::Key, Format<H>),
    /// `t-args`: dict or pairs merged into the call values.
    Args(Ex<H>),
}

/// The template called by `t-call`.
pub enum CallTarget<H: Host> {
    /// Fixed reference.
    Static(TemplateRef),
    /// Format string, rendered when called, then parsed like
    /// [`TemplateRef::parse`].
    Dynamic(Format<H>),
}

/// `t-call`.
pub struct Call<H: Host> {
    /// Block rendering the body (`values[0]`), if any.
    pub body: Option<usize>,
    /// Call values, in source order.
    pub args: Vec<CallArg<H>>,
    /// Called template.
    pub target: CallTarget<H>,
    /// Caller namespaces passed in the call options.
    pub nsmap: Option<NsMap>,
    /// Location of the `t-call` element.
    pub loc: Loc,
}

/// `t-foreach` / `t-as`, with the interned keys of the loop variables.
pub struct Foreach<H: Host> {
    /// Iterated expression, or a constant count for digit-only expressions.
    pub source: Result<Ex<H>, i64>,
    /// `x` (the `t-as` name).
    pub var: H::Key,
    /// `x_index`.
    pub index: H::Key,
    /// `x_value`.
    pub value: H::Key,
    /// `x_first`.
    pub first: H::Key,
    /// `x_last` (set only when the size is known).
    pub last: H::Key,
    /// `x_odd` (an int: 0 or 1).
    pub odd: H::Key,
    /// `x_even`.
    pub even: H::Key,
    /// `x_parity` (`'odd'` or `'even'`).
    pub parity: H::Key,
    /// `x_size` (set only when the size is known).
    pub size: H::Key,
    /// The str `'odd'`.
    pub parity_odd: H::Value,
    /// The str `'even'`.
    pub parity_even: H::Value,
    /// Loop body.
    pub body: Vec<Stmt<H>>,
    /// Location of the element.
    pub loc: Loc,
}

/// `t-call-assets`, rendered through [`Host::get_asset_nodes`].
pub struct Assets {
    /// Bundle name.
    pub bundle: Box<str>,
    /// `t-css` (default true).
    pub css: bool,
    /// `t-js` (default true).
    pub js: bool,
    /// `t-binary`.
    pub binary: bool,
    /// `t-autoprefix`.
    pub autoprefix: bool,
    /// `defer_load`.
    pub defer_load: bool,
    /// `lazy_load`.
    pub lazy_load: bool,
    /// `media`.
    pub media: Option<Box<str>>,
}

/// A statement of a compiled function body.
pub enum Stmt<H: Host> {
    /// `yield 'literal'`.
    Text(Box<str>),
    /// `if cond: then else: orelse` (`t-if` / `t-elif` / `t-else`).
    If {
        /// Condition.
        cond: Ex<H>,
        /// Branch run when the condition is true.
        then: Vec<Stmt<H>>,
        /// Branch run otherwise.
        orelse: Vec<Stmt<H>>,
        /// Location of the `t-if` element.
        loc: Loc,
    },
    /// `if user_has_groups(groups): body`.
    Groups {
        /// Comma-separated group xmlids (`!` negates).
        groups: Box<str>,
        /// Content.
        body: Vec<Stmt<H>>,
    },
    /// `t-foreach`.
    Foreach(Box<Foreach<H>>),
    /// `values[key] = expr`.
    Set {
        /// Variable.
        key: H::Key,
        /// Value.
        value: Ex<H>,
        /// Location of the element.
        loc: Loc,
    },
    /// `values[key] = format` (`t-valuef`), as `Markup` when `markup`.
    SetFormat {
        /// Variable.
        key: H::Key,
        /// Value.
        fmt: Format<H>,
        /// Wrap the result in `Markup`.
        markup: bool,
        /// Location of the element.
        loc: Loc,
    },
    /// `values.update(expr)`.
    SetUpdate {
        /// Dict value.
        value: Ex<H>,
        /// Location of the element.
        loc: Loc,
    },
    /// `values[key] = QwebContent(...)` rendering `block` lazily.
    SetLazy {
        /// Variable.
        key: H::Key,
        /// Index of the body in [`Program::blocks`].
        block: usize,
        /// Location of the element.
        loc: Loc,
    },
    /// `values[key] = value` for a constant (an empty `t-set` body).
    SetConst {
        /// Variable.
        key: H::Key,
        /// Value.
        value: H::Value,
    },
    /// `values['__qweb_options__'] = {**base, items...}`.
    Options {
        /// `t-options` expression.
        base: Option<Ex<H>>,
        /// `t-options-<name>` items.
        items: Vec<(H::Value, Ex<H>)>,
        /// Location of the element.
        loc: Loc,
    },
    /// `attrs = {}`.
    AttrsInit,
    /// `attrs[name] = value`.
    AttrSet {
        /// Attribute name.
        name: Arc<str>,
        /// Attribute value.
        value: AttrSrc<H>,
        /// Location of the element.
        loc: Loc,
    },
    /// `t-att` dict/pairs update.
    AttrUpdate {
        /// Dict, pair or list of pairs.
        value: Ex<H>,
        /// Location of the element.
        loc: Loc,
    },
    /// `if attrs: yield from self._render_attributes(tag, attrs); attrs = None`.
    AttrsFlush {
        /// Element tag (passed to the attribute post-processing).
        tag: Arc<str>,
    },
    /// `t-out` / `t-field`.
    Out(Box<Out<H>>),
    /// `yield values.get(0, '')`.
    Slot {
        /// Location of the element.
        loc: Loc,
    },
    /// `t-call`.
    Call(Box<Call<H>>),
    /// `t-call-assets`.
    Assets(Box<Assets>),
    /// Statement emitted by a custom directive (run by the host).
    Hook {
        /// Host payload.
        hook: H::Hook,
        /// Location of the element.
        loc: Loc,
    },
}

/// A compiled template.
pub struct Program<H: Host> {
    /// Function bodies; `main` is the template content.
    pub blocks: Vec<Vec<Stmt<H>>>,
    /// Index of the template body in `blocks`.
    pub main: usize,
    /// `values['xmlid']` / `values['viewid']` set when `xmlid` is missing.
    pub xmlid: H::Value,
    /// See `xmlid`.
    pub viewid: H::Value,
    /// Interned `"xmlid"`.
    pub xmlid_key: H::Key,
    /// Interned `"viewid"`.
    pub viewid_key: H::Key,
    /// Display name for errors.
    pub name: Arc<str>,
    /// Template reference for errors (`viewid` as text, or the name).
    pub reference: Arc<str>,
    /// Size of the last rendered output (to presize the output buffer).
    pub size_hint: std::sync::atomic::AtomicUsize,
    /// Source of the location texts.
    pub(crate) locs: LocSource,
}

impl<H: Host> Program<H> {
    /// `(path, element)` of a statement location, for error reporting.
    pub fn location(&self, loc: &Loc) -> (Arc<str>, Arc<str>) {
        self.locs.resolve(loc)
    }
}
